import pandas as pd

# 读取最新的Excel文件
df = pd.read_excel('/app/.hermes/cache/documents/doc_62a60f9d8630_CID title.xlsx')

# 查看基本信息
print("=== 新文件基本信息 ===")
print(f"行数: {len(df)}")
print(f"列数: {len(df.columns)}")

# 提取完整表头结构
print("\n=== 完整表头结构 ===")
current_main = None
current_sub = None

all_dimensions = {}

for i in range(len(df)):
    row = df.iloc[i]
    col1, col2, col3, col4 = row['Unnamed: 0'], row['Unnamed: 1'], row['Unnamed: 2'], row['Unnamed: 3']

    if pd.notna(col2):
        current_main = col2
    if pd.notna(col3):
        current_sub = col3
    if pd.notna(col4):
        if current_main not in all_dimensions:
            all_dimensions[current_main] = {}
        if current_sub not in all_dimensions[current_main]:
            all_dimensions[current_main][current_sub] = []
        all_dimensions[current_main][current_sub].append(col4)

# 打印所有维度
for main_cat, sub_cats in all_dimensions.items():
    print(f"\n【{main_cat}】")
    for sub_cat, values in sub_cats.items():
        print(f"  └─ {sub_cat}: {values}")
